import csv
import math
import sys
from collections import defaultdict


input_path, output_path = sys.argv[1], sys.argv[2]
rows = []
with open(input_path, newline="") as handle:
    reader = csv.DictReader(handle)
    required = {"cell_id", "time", "enh_x", "enh_y", "enh_z",
                "prom_x", "prom_y", "prom_z", "transcription"}
    if set(reader.fieldnames or []) != required:
        raise ValueError("unexpected columns: " + repr(reader.fieldnames))
    for r in reader:
        d = math.sqrt(
            (float(r["enh_x"]) - float(r["prom_x"])) ** 2
            + (float(r["enh_y"]) - float(r["prom_y"])) ** 2
            + (float(r["enh_z"]) - float(r["prom_z"])) ** 2
        )
        rows.append((int(r["cell_id"]), int(r["time"]), d,
                     int(d <= 260.0), int(r["transcription"])))

if len(rows) != 150000:
    raise ValueError("expected 150000 rows, observed %d" % len(rows))
by_cell = defaultdict(list)
for row in rows:
    by_cell[row[0]].append(row)
if len(by_cell) != 600 or any(len(x) != 250 for x in by_cell.values()):
    raise ValueError("unexpected cell/time dimensions")
for x in by_cell.values():
    x.sort(key=lambda z: z[1])
    if [z[1] for z in x] != list(range(250)):
        raise ValueError("nonconsecutive times")

out = []
out.append(("n_rows", len(rows), ""))
out.append(("n_cells", len(by_cell), ""))
out.append(("mean_distance_nm", sum(x[2] for x in rows) / len(rows), ""))
for c in (0, 1):
    subset = [x for x in rows if x[3] == c]
    out.append(("transcription_rate_given_contact", sum(x[4] for x in subset) / len(subset), "contact=%d;n=%d" % (c, len(subset))))
for t in (0, 1):
    subset = [x for x in rows if x[4] == t]
    out.append(("contact_rate_given_transcription", sum(x[3] for x in subset) / len(subset), "transcription=%d;n=%d" % (t, len(subset))))

# Cross-lag contrasts, stratified on the outcome's current state. This compares
# event initiation/persistence without confusing it with contemporaneous state.
for outcome_name, predictor_idx, outcome_idx in (("transcription", 3, 4), ("contact", 4, 3)):
    for current in (0, 1):
        counts = {0: [0, 0], 1: [0, 0]}
        for x in by_cell.values():
            for a, b in zip(x[:-1], x[1:]):
                if a[outcome_idx] == current:
                    p = a[predictor_idx]
                    counts[p][1] += 1
                    counts[p][0] += b[outcome_idx]
        rates = {}
        for p in (0, 1):
            rates[p] = counts[p][0] / counts[p][1]
            out.append(("next_%s_rate" % outcome_name, rates[p],
                        "current_%s=%d;predictor=%d;n=%d" %
                        (outcome_name, current, p, counts[p][1])))
        out.append(("crosslag_risk_difference", rates[1] - rates[0],
                    "predictor=%s;outcome=%s;current_outcome=%d" %
                    (("contact" if predictor_idx == 3 else "transcription"),
                     outcome_name, current)))

# Lead/lag raw conditional rates at lags -10..10. Positive lag means contact
# is observed first: contact(t) predicts transcription(t+lag).
for lag in range(-10, 11):
    counts = {0: [0, 0], 1: [0, 0]}
    for x in by_cell.values():
        by_time = {r[1]: r for r in x}
        for tm, r in by_time.items():
            target = by_time.get(tm + lag)
            if target is not None:
                counts[r[3]][1] += 1
                counts[r[3]][0] += target[4]
    r0 = counts[0][0] / counts[0][1]
    r1 = counts[1][0] / counts[1][1]
    out.append(("lagged_transcription_risk_difference", r1 - r0,
                "lag=%d;positive=contact_leads;n0=%d;n1=%d" %
                (lag, counts[0][1], counts[1][1])))

with open(output_path, "w", newline="") as handle:
    writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
    writer.writerow(["metric", "value", "stratum"])
    writer.writerows(out)

